  scope.executeClosure ?? (async () => ({ ok: false, issues: [{ code: 'NOT_IMPLEMENTED' }] }))

const H = 'a'.repeat(64)
const sha = (bytes) => createHash('sha256').update(bytes).digest('hex')
const issue = (r, code) => r.issues.some((x) => x.code === code)
const git = (root, ...args) => {
  const r = spawnSync('git', args, {
    cwd: root,
    encoding: 'utf8',
    env: {
      ...process.env,
      GIT_CONFIG_NOSYSTEM: '1',
      GIT_CONFIG_GLOBAL: process.platform === 'win32' ? 'NUL' : '/dev/null',
    },
  })
  assert.equal(r.status, 0, `${args.join(' ')}: ${r.stderr}`)
  return r.stdout.trim()
}

test('I21-01 two stages own unique independent changes and semantic map is frozen', () => {
  const m = manifest()
  m.id = 'other-direction'
  m.owner.branch = 'codex/other-direction'
  m.scope.planningAllowed = [
    'openspec/changes/alpha-change/**',
    'openspec/changes/beta-change/**',
    'docs/engineering/BRANCH-STATUS.md',
  ]
  m.scope.allowed = [
    'openspec/changes/alpha-change/**',
    'openspec/changes/beta-change/**',
    'docs/engineering/**',
  ]
  m.scope.closure.archiveOwner = 'alpha-change'
  m.scope.closure.archiveDestination =
    'openspec/changes/archive/<actual-archive-date>-alpha-change/**'
  m.scope.closure.specDestinations = ['openspec/specs/alpha-capability/spec.md']
  m.stages = [
    { ...m.stages[0], id: 'A01', change: 'alpha-change' },
    { ...m.stages[0], id: 'B02', change: 'beta-change' },
  ]
  assert.equal(validateManifest(m).ok, true)
  const before = scopeFingerprint(m)
  m.stages[1].change = 'gamma-change'
  m.scope.planningAllowed.push('openspec/changes/gamma-change/**')
  assert.notEqual(scopeFingerprint(m), before)
  m.scope.planningAllowed.pop()
  assert.ok(issue(validateManifest(m), 'STAGE_OWNER'))
  m.stages[1].change = 'beta-change'
  m.stages[0].dependencies = ['B02']
  m.stages[1].dependencies = ['A01']
  assert.ok(issue(validateManifest(m), 'DEPENDENCIES'))
})

